import urllib.request
url='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/efetch.fcgi?db=nuccore&id=NM_004235.6&rettype=gb&retmode=text'
data=urllib.request.urlopen(url).read().decode()
for line in data.splitlines():
    if line.strip().startswith('CDS'):
        print(line)
    if line.strip().startswith('5\\'UTR') or line.strip().startswith('3\\'UTR') or line.strip().startswith('sig_peptide') or line.strip().startswith('mat_peptide'):
        print(line)
